<?php require_once __DIR__.'/config.php';$number=$_GET['order']??'';$st=db()->prepare('SELECT * FROM orders WHERE order_number=?');$st->execute([$number]);$order=$st->fetch();if(!$order){http_response_code(404);exit('Pesanan tidak ditemukan.');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$file=$_FILES['proof']??null;$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024||!isset($allowed[mime_content_type($file['tmp_name'])])){$error='File harus JPG, JPEG, PNG, atau PDF dengan ukuran maksimal 5MB.';}else{$ext=$allowed[mime_content_type($file['tmp_name'])];$name=bin2hex(random_bytes(16)).'.'.$ext;$dir=__DIR__.'/uploads/payment-proofs';if(!is_dir($dir))mkdir($dir,0755,true);move_uploaded_file($file['tmp_name'],$dir.'/'.$name);db()->prepare("INSERT INTO payments(order_id,amount,proof_path) VALUES(?,?,?)")->execute([$order['id'],$order['total'],'uploads/payment-proofs/'.$name]);db()->prepare("UPDATE orders SET payment_status='waiting_verification' WHERE id=?")->execute([$order['id']]);flash('success','Bukti pembayaran terkirim dan menunggu verifikasi.');redirect('track.php');}}$title='Upload Payment Proof';require __DIR__.'/includes/header.php';?><main class="track-wrap"><div class="bg-white p-8 max-w-xl mx-auto"><div class="eyebrow">PAYMENT VERIFICATION</div><h1 class="serif text-4xl">Upload proof.</h1><p>Pesanan <b><?=e($order['order_number'])?></b> — <?=money((float)$order['total'])?></p><?php if(!empty($error)):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="field"><label>Bukti transfer (JPG, PNG, PDF maks. 5MB)</label><input required type="file" name="proof" accept=".jpg,.jpeg,.png,.pdf"></div><button class="btn gold w-full">SEND PAYMENT PROOF</button></form></div></main><?php require __DIR__.'/includes/footer.php'; ?>
